import math

class Solution:
    def numPoints(self, darts: List[List[int]], r: int) -> int:
        n = len(darts)
        ans = 1
        eps = 1e-5
        for i in range(n):
            x1, y1 = darts[i]
            for j in range(n):
                if i == j:
                    continue
                x2, y2 = darts[j]
                dx, dy = x2 - x1, y2 - y1
                d2 = dx * dx + dy * dy
                if d2 > 4 * r * r:
                    continue
                d = math.sqrt(d2)
                mx, my = (x1 + x2) / 2, (y1 + y2) / 2
                h = math.sqrt(max(0.0, r * r - d2 / 4))
                for sign in (1, -1):
                    cx = mx - sign * h * dy / d
                    cy = my + sign * h * dx / d
                    cnt = sum(1 for x, y in darts
                              if (x - cx) ** 2 + (y - cy) ** 2 <= r * r + eps)
                    ans = max(ans, cnt)
        return ans

