class Solution {
public:
    int numPoints(vector<vector<int>>& darts, int r) {
        int n = darts.size(), ans = 1;
        const double eps = 1e-5;
        for (int i = 0; i < n; i++) {
            double x1 = darts[i][0], y1 = darts[i][1];
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                double dx = darts[j][0] - x1, dy = darts[j][1] - y1;
                double d2 = dx * dx + dy * dy;
                if (d2 > 4.0 * r * r) continue;
                double d = sqrt(d2);
                double mx = (x1 + darts[j][0]) / 2, my = (y1 + darts[j][1]) / 2;
                double h = sqrt(max(0.0, (double)r * r - d2 / 4));
                for (int s = -1; s <= 1; s += 2) {
                    double cx = mx - s * h * dy / d;
                    double cy = my + s * h * dx / d;
                    int cnt = 0;
                    for (auto& p : darts) {
                        double ex = p[0] - cx, ey = p[1] - cy;
                        if (ex * ex + ey * ey <= (double)r * r + eps) cnt++;
                    }
                    ans = max(ans, cnt);
                }
            }
        }
        return ans;
    }
};

