class Solution {
public:
    int numPoints(vector<vector<int>>& darts, int r) {
        int n = darts.size(), ans = 1;
        const double eps = 1e-6;
        for (int i = 0; i < n; i++) {
            vector<pair<double,int>> ev;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                double dx = darts[j][0] - darts[i][0];
                double dy = darts[j][1] - darts[i][1];
                double d = hypot(dx, dy);
                if (d > 2.0 * r + eps || d < eps) continue;
                double base = atan2(dy, dx);
                double th = acos(min(1.0, d / (2.0 * r)));
                ev.push_back({base - th - eps, 1});
                ev.push_back({base + th + eps, -1});
            }
            sort(ev.begin(), ev.end(), [](auto& a, auto& b) {
                return a.first != b.first ? a.first < b.first : a.second > b.second;
            });
            int cur = 0;
            for (auto& e : ev) { cur += e.second; ans = max(ans, cur + 1); }
        }
        return ans;
    }
};

