import java.util.*;

class Solution {
    public int numPoints(int[][] darts, int r) {
        int n = darts.length, ans = 1;
        final double eps = 1e-6;
        for (int i = 0; i < n; i++) {
            List<double[]> ev = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                double dx = darts[j][0] - darts[i][0];
                double dy = darts[j][1] - darts[i][1];
                double d = Math.hypot(dx, dy);
                if (d > 2.0 * r + eps || d < eps) continue;
                double base = Math.atan2(dy, dx);
                double th = Math.acos(Math.min(1.0, d / (2.0 * r)));
                ev.add(new double[]{base - th - eps, 1});
                ev.add(new double[]{base + th + eps, -1});
            }
            ev.sort((a, b) -> a[0] != b[0]
                    ? Double.compare(a[0], b[0]) : Double.compare(b[1], a[1]));
            int cur = 0;
            for (double[] e : ev) { cur += (int) e[1]; ans = Math.max(ans, cur + 1); }
        }
        return ans;
    }
}

